function Styles() {
  return (
    <style>{`
      @import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@0,300;0,400;0,500;0,600;1,300;1,400;1,500&family=DM+Sans:wght@300;400;500;700&display=swap');
      @keyframes rotate-orbit { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
      @keyframes fade-up { from { opacity: 0; transform: translateY(30px); } to { opacity: 1; transform: translateY(0); } }
      @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
      @keyframes marquee-left { from { transform: translateX(0); } to { transform: translateX(-50%); } }
      @keyframes marquee-right { from { transform: translateX(-50%); } to { transform: translateX(0); } }
      @keyframes pulse-glow { 0%, 100% { opacity: 0.35; } 50% { opacity: 0.65; } }
      @keyframes blink-dot { 0%, 100% { opacity: 1; } 50% { opacity: 0.3; } }
      @keyframes float-soft { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-8px); } }
      .fade-up { animation: fade-up 1.1s cubic-bezier(0.22, 1, 0.36, 1) forwards; opacity: 0; }
      .fade-in { animation: fade-in 0.7s ease-out forwards; }
      .d1 { animation-delay: 0.05s; } .d2 { animation-delay: 0.2s; }
      .d3 { animation-delay: 0.4s; } .d4 { animation-delay: 0.6s; } .d5 { animation-delay: 0.8s; }
      .orbit { animation: rotate-orbit 40s linear infinite; }
      .marquee-l { animation: marquee-left 50s linear infinite; }
      .marquee-r { animation: marquee-right 55s linear infinite; }
      .marquee-slow { animation: marquee-left 80s linear infinite; }
      .marquee-slow-r { animation: marquee-right 90s linear infinite; }
      .glow-pulse { animation: pulse-glow 5s ease-in-out infinite; }
      .blink { animation: blink-dot 2s ease-in-out infinite; }
      .float-soft { animation: float-soft 6s ease-in-out infinite; }
      .grain {
        background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.5'/%3E%3C/svg%3E");
      }
      .serif { font-family: 'Fraunces', 'Times New Roman', serif; }
      .hover-lift { transition: all 0.5s cubic-bezier(0.22, 1, 0.36, 1); }
      .hover-lift:hover { transform: translateY(-6px); }
      .link-hover { transition: color 0.3s ease, opacity 0.3s ease; cursor: pointer; }
      .link-hover:hover { color: ${T.lilac}; }
      .page-enter { animation: fade-in 0.5s ease-out; }
    `}</style>
  );
}

