function PartnerChip({ name, index }) {
  // Subtle variation in chip style for visual rhythm — NOT clickable
  const variants = [
    { bg: 'rgba(168, 85, 247, 0.04)', border: 'rgba(168, 85, 247, 0.2)', fontStyle: 'italic' },
    { bg: 'rgba(192, 132, 252, 0.06)', border: 'rgba(192, 132, 252, 0.25)', fontStyle: 'normal' },
    { bg: 'rgba(10, 6, 18, 0.6)', border: 'rgba(168, 85, 247, 0.15)', fontStyle: 'italic' },
  ];
  const v = variants[index % 3];
  return (
    <div className="serif px-7 md:px-9 py-4 md:py-5 rounded-xl float-soft"
      style={{
        border: `1px solid ${v.border}`,
        background: v.bg,
        minWidth: 180,
        textAlign: 'center',
        fontStyle: v.fontStyle,
        fontSize: '1.05rem',
        letterSpacing: '0.08em',
        color: 'rgba(245, 243, 255, 0.72)',
        animationDelay: `${(index % 4) * 0.5}s`,
        whiteSpace: 'nowrap',
      }}>
      {name}
    </div>
  );
}

