// =========================================================================
// APP ROOT
// =========================================================================
export default function App() {
  const [page, setPage] = useState('home');
  const [blogPost, setBlogPost] = useState(null);
  const [mouse, setMouse] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const h = (e) => setMouse({ x: e.clientX, y: e.clientY });
    window.addEventListener('mousemove', h);
    return () => window.removeEventListener('mousemove', h);
  }, []);

  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [page, blogPost]);

  const goTo = (p) => {
    if (p !== 'blog') setBlogPost(null);
    setPage(p);
  };

  return (
    <div style={{ background: T.bg, color: T.ink, minHeight: '100vh', fontFamily: "'DM Sans', system-ui, sans-serif", overflowX: 'hidden' }}>
      <Styles />
      <AmbientBackground mouse={mouse} />
      <div style={{ position: 'relative', zIndex: 2 }}>
        <Nav page={page} setPage={goTo} />
        <main>
          {page === 'home' && <HomePage setPage={goTo} setBlogPost={(p) => { setBlogPost(p); setPage('blog'); }} />}
          {page === 'experience' && <ExperiencePage />}
          {page === 'blog' && !blogPost && <BlogListPage setBlogPost={setBlogPost} />}
          {page === 'blog' && blogPost && <BlogPostPage post={blogPost} onBack={() => setBlogPost(null)} />}
          {page === 'work' && <WorkPage />}
          {page === 'contact' && <ContactPage />}
        </main>
        <Footer />
      </div>
    </div>
  );
}
